/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import type { Sim } from "scenerystack/sim";
import { Tandem } from "scenerystack/tandem";
import { PlotBuilderScreen } from "../../src/builder/PlotBuilderScreen.js";
import { ExoplanetDatabase } from "../../src/common/model/ExoplanetDatabase.js";
import { CountsScreen } from "../../src/counts/CountsScreen.js";
import ExoplanetsDatabaseColors from "../../src/ExoplanetsDatabaseColors.js";
import { ExploreScreen } from "../../src/explore/ExploreScreen.js";
import { PlotGalleryScreen } from "../../src/gallery/PlotGalleryScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Filters, sort order and selection shared by the Explore table and the Plot Builder.
  const database = new ExoplanetDatabase();

  // The Plot Builder's "Show in Table" switches to the Explore screen; `sim` is assigned below.
  const sim = null as Sim | null;

  const screens = [
    new CountsScreen({
      name: stringManager.getScreenNames().countsStringProperty,
      tandem: Tandem.ROOT.createTandem("countsScreen"),
      backgroundColorProperty: ExoplanetsDatabaseColors.backgroundColorProperty,
    }),
    new ExploreScreen(database, {
      name: stringManager.getScreenNames().exploreStringProperty,
      tandem: Tandem.ROOT.createTandem("exploreScreen"),
      backgroundColorProperty: ExoplanetsDatabaseColors.backgroundColorProperty,
    }),
    new PlotGalleryScreen({
      name: stringManager.getScreenNames().galleryStringProperty,
      tandem: Tandem.ROOT.createTandem("galleryScreen"),
      backgroundColorProperty: ExoplanetsDatabaseColors.backgroundColorProperty,
    }),
    new PlotBuilderScreen(database, () => sim?.selectedScreenProperty.set(screens[1] as ExploreScreen), {
      name: stringManager.getScreenNames().builderStringProperty,
      tandem: Tandem.ROOT.createTandem("builderScreen"),
      backgroundColorProperty: ExoplanetsDatabaseColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { ExoplanetsDatabaseColors, stringManager, database } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
